mapper.select:
SELECT u.id AS user_id
FROM tbl_user u
LEFT JOIN tbl_asset_snapshot s
       ON s.user_id = u.id
      AND s.`year_month` = #{yearMonth}
WHERE u.status = 'ACTIVE'
  AND u.created_at < #{targetMonthEnd}
  AND (
      s.id IS NULL
      OR s.ai_analysis_status = 'NOT_REQUESTED'
      OR (
          s.ai_analysis_status = 'FAILED'
          AND s.ai_analysis_attempt_count < #{maxAutoAttempts}
          AND s.ai_analysis_failed_at IS NOT NULL
          AND s.ai_analysis_failed_at <= #{retryNotBefore}
          AND s.ai_analysis_failure_code IN ('TOO_MANY_REQUESTS', 'AI_PROVIDER_UNAVAILABLE')
      )
  )
ORDER BY u.id
